import importlib.util, json
payload = {'llama_cpp_import_ok': False}
try:
    import llama_cpp
    from llama_cpp import llama_cpp as low
    payload.update({
        'llama_cpp_import_ok': True,
        'llama_cpp_origin': importlib.util.find_spec('llama_cpp').origin,
        'llama_cpp_version': getattr(llama_cpp, '__version__', None),
        'llama_cpp_supports_gpu_offload': bool(low.llama_supports_gpu_offload()),
        'llama_cpp_supports_mmap': bool(low.llama_supports_mmap()),
    })
except Exception as exc:
    payload['error'] = f'{type(exc).__name__}: {exc}'
print(json.dumps(payload, sort_keys=True))

